create function public.retention_candidates(p_now timestamptz default now()) returns table(kind text,resource_id uuid,reason text) language sql security definer set search_path='' as $$
 select 'order',id,'unpaid_expired_30_days' from public.orders where internal_state='expired' and expires_at<p_now-interval '30 days'
 union all select 'order',id,'delivered_180_days_review_financial_obligations' from public.orders where internal_state='delivered' and delivered_at<p_now-interval '180 days'
 union all select 'source_attachment',a.id,'source_30_days_after_delivery' from public.attachments a join public.orders o on o.id=a.order_id where a.classification='source' and o.delivered_at<p_now-interval '30 days'
 union all select 'audit',id,'audit_180_days' from public.audit_events where created_at<p_now-interval '180 days'
 union all select 'consent',c.id,'revoked_180_days_and_no_public_media' from public.consent_events c where not c.granted and c.created_at<p_now-interval '180 days' and not exists(select 1 from public.public_media m where m.asset_id=c.asset_id and m.platform=c.scope and m.state in ('approved','published'));
$$;
create function public.cleanup_technical_ttl(p_dry_run boolean default true) returns jsonb language plpgsql security definer set search_path='' as $$declare n bigint;m bigint;begin select count(*) into n from public.abuse_counters where expires_at<now();select count(*) into m from public.lookup_sessions where expires_at<now() or revoked_at is not null;if not p_dry_run then delete from public.abuse_counters where expires_at<now();delete from public.lookup_sessions where expires_at<now() or revoked_at is not null;delete from public.asset_previews where expires_at<now();end if;return jsonb_build_object('dry_run',p_dry_run,'expired_counters',n,'expired_sessions',m);end$$;
create function public.complete_external_removal(p_actor uuid,p_task uuid) returns void language plpgsql security definer set search_path='' as $$begin perform public.require_admin(p_actor,true);update public.external_removal_tasks set state='completed',completed_by=p_actor,updated_at=now() where id=p_task and state='pending';if not found then raise exception 'task not pending';end if;insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'external_removal_verified_manually',p_task,array['state','completed_by']);end$$;
revoke all on function public.retention_candidates(timestamptz),public.cleanup_technical_ttl(boolean),public.complete_external_removal(uuid,uuid) from public,anon,authenticated;
grant execute on function public.retention_candidates(timestamptz),public.cleanup_technical_ttl(boolean),public.complete_external_removal(uuid,uuid) to service_role;
